CREATE TABLE permission_grants(workspace_id TEXT NOT NULL REFERENCES workspaces, actor_id TEXT NOT NULL, permission TEXT NOT NULL, resource_scope TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), revoked_at_ms INTEGER, PRIMARY KEY(workspace_id,actor_id,permission,resource_scope)) STRICT;
CREATE TABLE fact_revisions(workspace_id TEXT NOT NULL REFERENCES workspaces, product_id TEXT NOT NULL, field_key TEXT NOT NULL, revision TEXT NOT NULL, fact_proto BLOB NOT NULL, created_at_ms INTEGER NOT NULL, PRIMARY KEY(workspace_id,product_id,field_key,revision)) STRICT;
CREATE TRIGGER immutable_fact_revision BEFORE UPDATE ON fact_revisions BEGIN SELECT RAISE(ABORT,'fact history is immutable'); END;
CREATE TABLE invalidation_outbox(invalidation_id INTEGER PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces, reason TEXT NOT NULL, resource_id TEXT NOT NULL, old_revision TEXT NOT NULL, new_revision TEXT NOT NULL, created_at_ms INTEGER NOT NULL, acknowledged_at_ms INTEGER) STRICT;
CREATE TABLE managed_artifacts(workspace_id TEXT NOT NULL REFERENCES workspaces, artifact_id TEXT NOT NULL, path TEXT NOT NULL, sha256 TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes BETWEEN 0 AND 16777216), kind TEXT NOT NULL CHECK(kind IN('knowledge','assets','models')), PRIMARY KEY(workspace_id,artifact_id), UNIQUE(workspace_id,path)) STRICT;
